-- Add specific gravity GLB profiles. No published resources, Auth, RLS or tables are changed.
create or replace function iam.valid_visual_manifest(value jsonb) returns boolean language sql immutable set search_path='' as $function$
select value is not null and extensions.jsonb_matches_schema($schema${"$schema":"http://json-schema.org/draft-07/schema#","type":"object","properties":{"manifest_version":{"type":"number","const":1},"units":{"type":"string","const":"meters"},"origin":{"type":"string","minLength":1,"maxLength":80,"pattern":"^[a-z][a-z0-9_]*$"},"parameters":{"default":{},"type":"object","properties":{"size_scale":{"type":"number","minimum":0.7,"maximum":1.4},"profile_key":{"type":"string","enum":["commencal-meta-sx-v5","ohlins-rxf38-m3","fox-38-factory-my27","rockshox-vivid-coil-ultimate-d1","marzocchi-bomber-cr","shimano-slx-m7120","shimano-slx-oem-165-32","shimano-sm-bb71-41a","shimano-slx-rd-m7100-sgs","shimano-slx-cs-m7100-12","shimano-slx-cn-m7100","shimano-sm-rt86","dt-swiss-e-593","dt-swiss-350","maxxis-assegai","maxxis-minion-dhr-ii","rockbros-nylon-2017-12","atlas-handlebar-v1","atlas-stem-v1","atlas-saddle-v1","atlas-seatpost-v1","commencal-supreme-dh-v5","fox-40-factory-my27","sram-gx-dh-a3","sram-xg-795","sram-pc1110","sram-dub-pressfit","truvativ-descendant-dh","atlas-potencia-directa","shimano-slx-m7100-brake","magura-mt4","magura-mt5","magura-mt5-pro","magura-mt7-pro","sram-maven-brz-b1","sram-maven-slv-b1","sram-maven-ult-b1","magura-mdr-p","sram-hs2","rockshox-zeb-ultimate-b1","marzocchi-bomber-z1-rail","fox-float-x2-factory-my26","ohlins-ttx22m2-coil","santa-cruz-nomad-7-my27","canyon-sender-cfr-high-pivot","specialized-s-works-enduro-udh","da-bomb-cherry-bomb-29","scott-ransom-rc-427727","trek-slash-al-gen-6","cst-bft-c1752","kenda-pinner-pro-k1241a","michelin-wild-enduro-ms-racing-line","schwalbe-gravity-magic-mary","renthal-fatbar-35","deity-racepoint-35","renthal-apex-35","renthal-integra-35","oneup-v3-dropper","wtb-volt","santa-cruz-v10-8-my27","yt-tues-mk4-carbon","yt-capra-mk3-carbon-mx","gt-fury-carbon-high-pivot","gt-force-carbon-high-pivot","commencal-frs-v3","commencal-furious-v3-2021","rockshox-boxxer-ultimate-d2","rockshox-boxxer-select-d2","marzocchi-bomber-58","ohlins-dh38-m2"]},"assembly_version":{"type":"string","const":"atlas-assembly-v5"},"mount_space":{"type":"string","enum":["frame","fork","shock"]}},"additionalProperties":false},"anchors":{"default":{},"type":"object","propertyNames":{"type":"string","pattern":"^[a-z][a-z0-9_]*$"},"additionalProperties":{"type":"object","properties":{"position":{"type":"array","items":[{"type":"number","minimum":-5,"maximum":5},{"type":"number","minimum":-5,"maximum":5},{"type":"number","minimum":-5,"maximum":5}],"additionalItems":false,"minItems":3,"maxItems":3},"rotation":{"type":"array","items":[{"type":"number","minimum":-6.283185307179586,"maximum":6.283185307179586},{"type":"number","minimum":-6.283185307179586,"maximum":6.283185307179586},{"type":"number","minimum":-6.283185307179586,"maximum":6.283185307179586}],"additionalItems":false,"minItems":3,"maxItems":3},"estimated":{"type":"boolean"}},"required":["position","rotation","estimated"],"additionalProperties":false}},"paintable_nodes":{"default":[],"maxItems":128,"type":"array","items":{"type":"string","minLength":1,"maxLength":150}},"selectable_nodes":{"default":[],"maxItems":128,"type":"array","items":{"type":"string","minLength":1,"maxLength":150}}},"required":["manifest_version","units","origin","parameters","anchors","paintable_nodes","selectable_nodes"],"additionalProperties":false}$schema$::json,value);
$function$;
revoke all on function iam.valid_visual_manifest(jsonb) from public,anon,authenticated;
create or replace function iam.visual_profile_category(profile text) returns text language sql immutable set search_path='' as $function$
select $profiles${"commencal-meta-sx-v5":"frame","ohlins-rxf38-m3":"fork","fox-38-factory-my27":"fork","rockshox-vivid-coil-ultimate-d1":"shock","marzocchi-bomber-cr":"shock","shimano-slx-m7120":"brake","shimano-slx-oem-165-32":"crankset","shimano-sm-bb71-41a":"bottom_bracket","shimano-slx-rd-m7100-sgs":"rear_derailleur","shimano-slx-cs-m7100-12":"cassette","shimano-slx-cn-m7100":"chain","shimano-sm-rt86":"rotor","dt-swiss-e-593":"rim","dt-swiss-350":"hub","maxxis-assegai":"tire","maxxis-minion-dhr-ii":"tire","rockbros-nylon-2017-12":"pedals","atlas-handlebar-v1":"handlebar","atlas-stem-v1":"stem","atlas-saddle-v1":"saddle","atlas-seatpost-v1":"seatpost","commencal-supreme-dh-v5":"frame","fox-40-factory-my27":"fork","sram-gx-dh-a3":"rear_derailleur","sram-xg-795":"cassette","sram-pc1110":"chain","sram-dub-pressfit":"bottom_bracket","truvativ-descendant-dh":"crankset","atlas-potencia-directa":"stem","shimano-slx-m7100-brake":"brake","magura-mt4":"brake","magura-mt5":"brake","magura-mt5-pro":"brake","magura-mt7-pro":"brake","sram-maven-brz-b1":"brake","sram-maven-slv-b1":"brake","sram-maven-ult-b1":"brake","magura-mdr-p":"rotor","sram-hs2":"rotor","rockshox-zeb-ultimate-b1":"fork","marzocchi-bomber-z1-rail":"fork","fox-float-x2-factory-my26":"shock","ohlins-ttx22m2-coil":"shock","santa-cruz-nomad-7-my27":"frame","canyon-sender-cfr-high-pivot":"frame","specialized-s-works-enduro-udh":"frame","da-bomb-cherry-bomb-29":"frame","scott-ransom-rc-427727":"frame","trek-slash-al-gen-6":"frame","cst-bft-c1752":"tire","kenda-pinner-pro-k1241a":"tire","michelin-wild-enduro-ms-racing-line":"tire","schwalbe-gravity-magic-mary":"tire","renthal-fatbar-35":"handlebar","deity-racepoint-35":"handlebar","renthal-apex-35":"stem","renthal-integra-35":"stem","oneup-v3-dropper":"seatpost","wtb-volt":"saddle","santa-cruz-v10-8-my27":"frame","yt-tues-mk4-carbon":"frame","yt-capra-mk3-carbon-mx":"frame","gt-fury-carbon-high-pivot":"frame","gt-force-carbon-high-pivot":"frame","commencal-frs-v3":"frame","commencal-furious-v3-2021":"frame","rockshox-boxxer-ultimate-d2":"fork","rockshox-boxxer-select-d2":"fork","marzocchi-bomber-58":"fork","ohlins-dh38-m2":"fork"}$profiles$::jsonb ->> profile;
$function$;
revoke all on function iam.visual_profile_category(text) from public,anon,authenticated;
alter table public.visual_assets add constraint gravity_profile_glb_contract check(manifest->'parameters'->>'profile_key' not in ('santa-cruz-v10-8-my27','yt-tues-mk4-carbon','yt-capra-mk3-carbon-mx','gt-fury-carbon-high-pivot','gt-force-carbon-high-pivot','commencal-frs-v3','commencal-furious-v3-2021','rockshox-boxxer-ultimate-d2','rockshox-boxxer-select-d2','marzocchi-bomber-58','ohlins-dh38-m2') or coalesce(kind='glb' and generator_key is null and manifest->'parameters'->>'mount_space'=iam.visual_profile_category(manifest->'parameters'->>'profile_key'),false));
